Q: YouTube embedded playback in Android Kotlin app fails with error 152-4 even though onReady fires Body A: <p>I faced this same issue in my app using the same dependency. the problem is not the dependency but new youtube policies for embeds. YouTube has recently updated its security to require a very specific <strong>referer policy</strong> and a valid <strong>Origin</strong>. the fix?</p>
<ol>
<li><p><strong>Meta Tag:</strong> Adding a <code>&lt;meta&gt;</code> tag to the HTML head to force the referrer policy.</p>
</li>
<li><p><strong>IFrame Attribute:</strong> Explicitly adding <code>referrerpolicy=&quot;strict-origin-when-cross-origin&quot;</code> to the iframe.</p>
</li>
<li><p><strong>Realistic Base URL:</strong> Instead of using <code>youtube.com</code> as the base, use your actual app's website or a placeholder domain that looks like a real site.</p>
<pre><code>
import android.view.ViewGroup
import android.webkit.WebChromeClient
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.compose.foundation.layout.aspectRatio
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.viewinterop.AndroidView

@Composable
fun YouTubeIFramePlayer(
    videoId: String,
    modifier: Modifier = Modifier
) {

    val html = &quot;&quot;&quot;
        &lt;!DOCTYPE html&gt;
        &lt;html&gt;
        &lt;head&gt;
            &lt;meta name=&quot;referrer&quot; content=&quot;strict-origin-when-cross-origin&quot;&gt;
            &lt;style&gt;
                body { margin: 0; padding: 0; background-color: black; }
                .video-container { position: relative; padding-bottom: 56.25%; height: 0; overflow: hidden; }
                .video-container iframe { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
            &lt;/style&gt;
        &lt;/head&gt;
        &lt;body&gt;
            &lt;div class=&quot;video-container&quot;&gt;
                &lt;iframe 
                    id=&quot;player&quot;
                    src=&quot;https://www.youtube.com/embed/$videoId?autoplay=1&amp;modestbranding=1&amp;rel=0&amp;enablejsapi=1&quot; 
                    allow=&quot;autoplay; encrypted-media; picture-in-picture&quot; 
                    allowfullscreen
                    /* FIX 2: Explicit Policy on the Iframe itself */
                    referrerpolicy=&quot;strict-origin-when-cross-origin&quot;&gt;
                &lt;/iframe&gt;
            &lt;/div&gt;
        &lt;/body&gt;
        &lt;/html&gt;
    &quot;&quot;&quot;.trimIndent()

    AndroidView(
        modifier = modifier
            .fillMaxWidth()
            .aspectRatio(16 / 9f),
        factory = { context -&gt;
            WebView(context).apply {
                layoutParams = ViewGroup.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT,
                    ViewGroup.LayoutParams.MATCH_PARENT
                )

                settings.apply {
                    javaScriptEnabled = true
                    domStorageEnabled = true
                    mediaPlaybackRequiresUserGesture = false
                    useWideViewPort = true
                    loadWithOverviewMode = true
                    // Spoofing a very specific modern Chrome agent
                    userAgentString = &quot;Mozilla/5.0 (Linux; Android 13; Samsung-SM-G991B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Mobile Safari/537.36&quot;
                }

                webViewClient = WebViewClient()
                webChromeClient = WebChromeClient()

                val appBaseUrl = &quot;https://anywebsite.com&quot; 

                loadDataWithBaseURL(appBaseUrl, html, &quot;text/html&quot;, &quot;UTF-8&quot;, null)
            }
        },
        onRelease = { webView -&gt;
            webView.destroy()
        }
    )
}
</code></pre>
</li>
</ol>
